import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();

        // Initialize memo array
        memo = new HashMap[n + 1][2];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                memo[i][j] = new HashMap<>();
            }
        }

        int ans = solve(n, 0, 1) % mod;
        System.out.println(ans);
        sc.close();
    }

    // Function to compute invnum for a sequence
    public static int invnum(int[] seq) {
        int N = seq.length;
        int res = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (seq[i] > seq[j]) {
                    res++;
                }
            }
        }
        return res;
    }

    // Helper function to generate all permutations
    public static void permutations(int[] array, int start, java.util.List<int[]> perms) {
        if (start == array.length - 1) {
            perms.add(array.clone());
            return;
        }
        for (int i = start; i < array.length; i++) {
            swap(array, start, i);
            permutations(array, start + 1, perms);
            swap(array, start, i);
        }
    }

    public static void swap(int[] array, int i, int j) {
        int tmp = array[i];
        array[i] = array[j];
        array[j] = tmp;
    }

    // Function to generate all permutations of range(N)
    public static java.util.List<int[]> generatePermutations(int N) {
        int[] base = new int[N];
        for (int i = 0; i < N; i++) {
            base[i] = i;
        }
        java.util.List<int[]> perms = new java.util.ArrayList<>();
        permutations(base, 0, perms);
        return perms;
    }

    static int solve(int N, int k, int flag) {
        if (memo[N][flag].containsKey(k)) {
            return memo[N][flag].get(k);
        }

        int res;
        if (N == 1) {
            res = -1;
            if (flag == 1) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo[N][flag].put(k, res);
            return res;
        }
        int invnum_INF = (N * (N - 1)) / 2;

        if (k < -invnum_INF - 1) {
            res = solve(N, -invnum_INF - 1, flag);
            memo[N][flag].put(k, res);
            return res;
        }
        if (k >= invnum_INF) {
            res = 0;
            memo[N][flag].put(k, res);
            return res;
        }

        res = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag == 1 && delta > 0) {
                continue;
            }

            int wt = Math.min(N - delta, delta + N);
            int[] pSeq = new int[N];
            for (int i = 0; i < N; i++) {
                pSeq[i] = i;
            }
            java.util.List<int[]> pPerms = new java.util.ArrayList<>();
            permutations(pSeq, 0, pPerms);
            int count_q = 0;
            for (int[] p : pPerms) {
                int[] q = p.clone();
                // Generate permutations q
                // For simplicity, we generate all permutations of range N
                for (int[] qPerm : pPerms) {
                    int invDiff = invnum(p) - invnum(qPerm);
                    if (((pCompare(p, qPerm) < 0) || (flag == 0)) && (invDiff > k)) {
                        res += wt;
                        res %= mod;
                        break; // Count once per valid q permutation
                    }
                }
            }
        }

        int finalRes = res % mod;
        memo[N][flag].put(k, finalRes);
        return finalRes;
    }

    // Comparison function for permutations
    public static int pCompare(int[] p, int[] q) {
        for (int i = 0; i < p.length; i++) {
            if (p[i] != q[i]) {
                return Integer.compare(p[i], q[i]);
            }
        }
        return 0;
    }
}

